+/// Sentinel: our transaction is mined but not durable yet. Keep the task, change nothing,
+/// and come back next cycle - do **not** send anything at this nonce again.
+///
+/// Distinct from `"PendingReplacement"` on purpose. That one means "still in the mempool,
+/// replace it with a higher fee next cycle"; this one means "already on chain, replacing
+/// it would be a duplicate". Matched by exact string in `dispatcher.rs` and
+/// `epoch_watcher.rs`, like every other sentinel in this crate.
+pub const AWAITING_FINALITY: &str = "AwaitingFinality";
+
+/// Sentinels meaning "this transaction is still ours": either in the mempool
+/// (`PendingReplacement`) or mined but not yet durable ([`AWAITING_FINALITY`]).
+///
+/// A task must return these untouched instead of falling through to its "did someone else
+/// do it?" checks. Those read the chain, and for a mined-but-not-durable transaction they
+/// would find *our own* effect, read it as a lost race, and retire the task - which is the
+/// exact hole the durability gate closes.
+pub fn is_in_flight(err: &(dyn std::error::Error + Send + Sync)) -> bool {
+    let msg = err.to_string();
+    msg == "PendingReplacement" || msg == AWAITING_FINALITY
+}
+
+/// How durable a write has to be before [`send_or_replace`] reports success.
+///
+/// One confirmation is not durability: the dispatcher retires a task the moment its
+/// action returns `Ok(())`, so a transaction reorged out after that confirmation is never
+/// re-sent and never re-observed.
+#[derive(Clone)]
+pub enum Durability {
+    /// One confirmation, no gate.
+    ///
+    /// Only for writes whose caller re-derives its own state from the chain on every
+    /// cycle, so a gate here would be escaped immediately and would leave an uncleared
+    /// pending record behind. `claim` is the sole case - see `tasks/claim.rs`.
+    Confirmed,
+    /// The sending chain's own `finalized` tag has reached the receipt's block.
+    ///
+    /// The bar for every settlement-chain write: Ethereum and Gnosis both finalize under
+    /// their own consensus, and their `finalized` tag is exactly "cannot be reorged".
+    ChainFinalized,
+    /// Arbitrum L2: the receipt's block sits in a sequencer batch whose L1 posting block
+    /// is finalized.
+    ///
+    /// An L2 block is only as durable as the L1 batch carrying it, so the raw L2
+    /// `finalized` tag is not the bar here - see [`crate::finality::is_l2_block_finalized`].
+    ArbitrumBatchFinalized {
+        l1_provider: DynProvider<Ethereum>,
+        sequencer_inbox: Option<Address>,
+    },
+}
+
+impl Durability {
+    /// Whether a receipt in `receipt_block` on `provider`'s chain clears this bar.
+    async fn is_durable(
+        &self,
+        provider: &DynProvider<Ethereum>,
+        receipt_block: u64,
+    ) -> Result<bool, Box<dyn std::error::Error + Send + Sync>> {
+        match self {
+            Durability::Confirmed => Ok(true),
+            Durability::ChainFinalized => {
+                let finalized = provider
+                    .get_block_by_number(alloy::eips::BlockNumberOrTag::Finalized)
+                    .await?
+                    .map(|block| block.header.number);
+                Ok(block_is_finalized(receipt_block, finalized))
+            }
+            Durability::ArbitrumBatchFinalized { l1_provider, sequencer_inbox } => {
+                crate::finality::is_l2_block_finalized(receipt_block, provider, l1_provider, *sequencer_inbox).await
+            }
+        }
+    }
+}
+
+/// The settlement-chain bar: a receipt is durable once the chain's own `finalized` tag has
+/// reached its block.
+///
+/// `None` is "the node served no finalized block" - an RPC that cannot answer is not
+/// evidence of durability, so it counts as not durable and the caller waits.
+const fn block_is_finalized(receipt_block: u64, finalized_block: Option<u64>) -> bool {
+    match finalized_block {
+        Some(finalized) => finalized >= receipt_block,
+        None => false,
+    }
+}
+
+/// What the chain's answer about an already-broadcast nonce means for the task.
+#[derive(Debug, Clone, Copy, PartialEq, Eq)]
+enum MinedOutcome {
+    /// Mined, succeeded, durable: the write is done for good.
+    Settled,
+    /// Mined and succeeded, but still reorgable: wait, and do not touch the nonce.
+    AwaitFinality,
+    /// Mined and reverted. Terminal: the nonce is spent, so a retry needs a fresh one.
+    Reverted,
+    /// No receipt at all - never mined, or reorged back out. Send again at the same nonce.
+    Resend,
+}
+
+/// `receipt` is `None` when the chain has no receipt for the transaction we broadcast, and
+/// `Some((succeeded, durable))` when it has one.
+///
+/// A reverted receipt is terminal whether or not it is durable: the revert consumed the
+/// nonce, so there is nothing to wait for, and the caller's own post-revert checks decide
+/// what happens next.
+const fn mined_outcome(receipt: Option<(bool, bool)>) -> MinedOutcome {
+    match receipt {
+        None => MinedOutcome::Resend,
+        Some((false, _)) => MinedOutcome::Reverted,
+        Some((true, false)) => MinedOutcome::AwaitFinality,
+        Some((true, true)) => MinedOutcome::Settled,
+    }
+}
+
+/// What the chain currently says about a transaction we broadcast.
+///
+/// Every uncertainty resolves to [`MinedOutcome::AwaitFinality`] rather than
+/// [`MinedOutcome::Resend`]: an RPC that will not answer is not evidence that a
+/// transaction is absent, and waiting another cycle is always recoverable where re-sending
+/// over a mined write is not.
+async fn broadcast_outcome(
+    provider: &DynProvider<Ethereum>,
+    hash: FixedBytes<32>,
+    durability: &Durability,
+    action: &str,
+    route_name: &str,
+) -> MinedOutcome {
+    let receipt = match provider.get_transaction_receipt(hash).await {
+        Ok(receipt) => receipt,
+        Err(e) => {
+            warn!(logger = "Task", route = route_name, action, "Could not read the receipt ({e}), waiting rather than re-sending");
+            return MinedOutcome::AwaitFinality;
+        }
+    };
+
+    let receipt = match receipt {
+        Some(receipt) => receipt,
+        // The only path that re-sends: the chain has no receipt, so the transaction either
+        // never mined or was reorged back out.
+        None => return MinedOutcome::Resend,
+    };
+
+    let block = match receipt.block_number {
+        Some(block) => block,
+        None => {
+            warn!(logger = "Task", route = route_name, action, "Receipt carries no block number, waiting");
+            return MinedOutcome::AwaitFinality;
+        }
+    };
+
+    mined_outcome(Some((receipt.status(), is_durable(provider, durability, block, action, route_name).await)))
+}
+
+/// [`Durability::is_durable`] with the RPC failure folded in as "not durable yet".
+///
+/// A failed durability read must never be reported as durable: that would retire the task
+/// on exactly the evidence the gate exists to demand.
+async fn is_durable(
+    provider: &DynProvider<Ethereum>,
+    durability: &Durability,
+    block: u64,
+    action: &str,
+    route_name: &str,
+) -> bool {
+    match durability.is_durable(provider, block).await {
+        Ok(durable) => durable,
+        Err(e) => {
+            warn!(logger = "Task", route = route_name, action, block, "Durability check failed ({e}), treating as not final");
+            false
+        }
+    }
+}
+
+/// Apply a [`MinedOutcome`] to the pending record and turn it into what [`send_or_replace`]
+/// returns; `None` means "not resolved here", i.e. fall through to the replacement path.
+///
+/// The pending record is cleared for every terminal outcome and deliberately *kept* for
+/// [`MinedOutcome::AwaitFinality`]: it is what stops the next cycle from re-sending a
+/// transaction that is already on chain, and what lets that cycle re-check the very same
+/// nonce instead of claiming a new one.
+fn settle(
+    task_store: &Arc<Mutex<TaskStore>>,
+    key: &str,
+    outcome: MinedOutcome,
+    action: &str,
+    route_name: &str,
+) -> Option<Result<(), Box<dyn std::error::Error + Send + Sync>>> {
+    match outcome {
+        MinedOutcome::Settled => {
+            task_store.lock().unwrap().clear_pending_tx(key);
+            info!(logger = "Task", route = route_name, action, "Transaction succeeded and is final");
+            Some(Ok(()))
+        }
+        MinedOutcome::AwaitFinality => {
+            info!(logger = "Task", route = route_name, action, "Transaction mined, waiting for it to become final");
+            Some(Err(AWAITING_FINALITY.into()))
+        }
+        MinedOutcome::Reverted => {
+            task_store.lock().unwrap().clear_pending_tx(key);
+            Some(Err(format!("[{}] {} reverted", route_name, action).into()))
+        }
+        MinedOutcome::Resend => None,
+    }
+}
+
 /// Send `call`, or replace this task's in-flight transaction with a fee-bumped one at
 /// the same nonce.
 ///
@@ -140,6 +343,16 @@ pub async fn blocking_nonce(provider: &DynProvider<Ethereum>, address: Address)
 /// afterwards would be unreliable: a node that has not yet seen the transaction answers
 /// null, and losing the nonce would let the next cycle send a duplicate, which is the
 /// exact failure this function exists to prevent.
+///
+/// `Ok(())` means the write cleared `durability`, not merely that it confirmed. Until it
+/// does, the pending record stays and this returns [`AWAITING_FINALITY`] so the caller's
+/// task survives to re-check the same nonce. A nonce whose receipt has disappeared is
+/// re-sent through the usual fee-bump path; one that still has a receipt is never re-sent.
+// Eight arguments, all of them distinct context a caller already holds separately (the call,
+// the chain, the signer, the store, the epoch, two log labels, the durability bar). Grouping
