@@ -160,6 +374,21 @@ where
     // across the awaits below, which would make this future non-`Send`.
     let existing = task_store.lock().unwrap().get_pending_tx(&key);

+    // Re-entry: settle the nonce we already broadcast at before considering a replacement.
