@@ -219,12 +454,15 @@ where

     match pending.with_timeout(Some(RECEIPT_TIMEOUT)).get_receipt().await {
         Ok(receipt) => {
-            task_store.lock().unwrap().clear_pending_tx(&key);
-            if !receipt.status() {
-                return Err(format!("[{}] {} reverted", route_name, action).into());
-            }
