         }
         Err(e) => {
             warn!(logger = "Task", route = route_name, action, nonce, "Receipt not seen ({e}), will replace next cycle");
@@ -277,6 +515,17 @@ pub struct PendingTx {
     pub nonce: u64,
     pub max_fee: u128,
     pub priority_fee: u128,
+    /// Hash of the last transaction broadcast at this nonce, once it has been broadcast.
+    ///
+    /// The only way to ask the chain about a specific transaction: `eth_getTransactionCount`
+    /// answers about the nonce, not about *our* attempt at it, so the durability gate in
+    /// [`send_or_replace`] needs the hash to fetch a receipt on re-entry.
+    ///
+    /// `None` covers both "recorded, not yet broadcast" and a record written by a version
+    /// of the bot that predates this field; `send_or_replace` treats both as "nothing to
+    /// look up" and falls through to a same-nonce re-send.
+    #[serde(default)]
+    pub tx_hash: Option<FixedBytes<32>>,
 }

 /// Key for [`RouteState::pending_txs`] - one in-flight transaction per action per epoch.
@@ -290,10 +539,6 @@ pub enum TaskKind {
     SaveSnapshot,
