+    }
+
+    #[test]
+    fn is_in_flight_covers_both_sentinels_and_nothing_else() {
+        let in_flight: [Box<dyn std::error::Error + Send + Sync>; 2] =
+            ["PendingReplacement".into(), AWAITING_FINALITY.into()];
+        for err in &in_flight {
+            assert!(is_in_flight(err.as_ref()), "{err} means the transaction is still ours");
+        }
