use alloy::providers::Provider;
use std::sync::{Arc, Mutex};
use tokio::time::{sleep, Duration};
use tracing::{info, warn};

use crate::config::{Route, ValidatorConfig};
use crate::tasks;
use crate::tasks::{Task, TaskKind, TaskStore, ClaimStore};

const POLL_INTERVAL: Duration = Duration::from_secs(15);

pub struct TaskDispatcher {
    config: ValidatorConfig,
    route: Route,
    task_store: Arc<Mutex<TaskStore>>,
    claim_store: Arc<Mutex<ClaimStore>>,
}

impl TaskDispatcher {
    pub fn new(
        config: ValidatorConfig,
        route: Route,
        task_store: Arc<Mutex<TaskStore>>,
        claim_store: Arc<Mutex<ClaimStore>>,
    ) -> Self {
        Self {
            config,
            route,
            task_store,
            claim_store,
        }
    }

    pub async fn run(&self) {
        loop {
            self.process_pending().await;
            sleep(POLL_INTERVAL).await;
        }
    }

    pub async fn process_pending(&self) {
        if !self.task_store.lock().unwrap().is_on_sync() {
            return;
        }

        let state = self.task_store.lock().unwrap().load();

        let now = match self.route.outbox_provider.get_block_by_number(Default::default()).await {
            Ok(Some(block)) => block.header.timestamp,
            _ => {
                warn!(logger = "Dispatcher", route = self.route.name, "Failed to get latest block, retrying next cycle");
                return;
            }
        };

        let ready: Vec<Task> = state
            .tasks
            .iter()
            .filter(|t| now >= t.execute_after)
            .cloned()
            .collect();

        if ready.is_empty() {
            return;
        }

        info!(logger = "Dispatcher", route = self.route.name, count = ready.len(), "Processing ready tasks");

        for task in ready {
            info!(logger = "Dispatcher", route = self.route.name, task = task.kind.name(), epoch = task.epoch, "Executing task");
            let success = self.execute_task(&task, now).await;
            if success {
                info!(logger = "Dispatcher", route = self.route.name, task = task.kind.name(), epoch = task.epoch, "Completed task");
                self.task_store.lock().unwrap().remove_task(&task);
            }
        }
    }

    /// Returns whether the task is finished with. `true` makes the caller call
    /// `remove_task`, which matches on `(epoch, kind)` only - so an arm that rescheduled
    /// the task must return `false`, or the reschedule is undone by the removal.
    async fn execute_task(&self, task: &Task, current_timestamp: u64) -> bool {
        let epoch = task.epoch;
        let wallet_address = self.config.wallet.default_signer().address();
        match &task.kind {
            TaskKind::SaveSnapshot => {
                tasks::save_snapshot::execute(&self.route, &self.task_store).await.is_ok()
            }
            TaskKind::Claim { .. } => {
                tasks::claim::execute(
                    &self.config,
                    &self.route,
                    epoch,
                    &self.claim_store,
                    current_timestamp,
                    &self.task_store,
                ).await.is_ok()
            }
            TaskKind::ValidateClaim => {
                match tasks::validate_claim::execute(
                    &self.config,
                    &self.route,
                    epoch,
                    &self.claim_store,
                    current_timestamp,
                    &self.task_store,
                ).await {
                    Ok(_) => true,
                    Err(e) if e.to_string() == "EpochNotFinalized" => {
                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
                        true
                    }
                    Err(_) => false,
                }
            }
            TaskKind::Challenge => {
                match tasks::challenge::execute(&self.config, &self.route, epoch, &self.claim_store, &self.task_store).await {
                    Ok(_) => true,
                    // In flight: keep the task as-is so the next cycle replaces it.
                    Err(e) if e.to_string() == "PendingReplacement" => false,
                    // Mined but not durable. Keeping the task is the whole point: if the
                    // transaction is reorged out, the next cycle finds no receipt and
                    // re-sends it at the same nonce.
                    Err(e) if e.to_string() == tasks::AWAITING_FINALITY => false,
                    Err(e) if e.to_string() == "Insufficient funds" => {
                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
                        true
                    }
                    Err(e) if e.to_string() == "VerificationStarted" => {
                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 20 * 60);
                        true
                    }
                    Err(e) if e.to_string().contains("Invalid claim") => {
                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
                        true
                    }
                    Err(_) => false,
                }
            }
            TaskKind::SendSnapshot => {
                match tasks::send_snapshot::execute(&self.config, &self.route, epoch, &self.claim_store, &self.task_store, wallet_address).await {
                    Ok(_) => true,
                    Err(e) if e.to_string() == "PendingReplacement" => false,
                    // The L2 bar: the snapshot's batch is not posted-and-finalized on L1
                    // yet, so the task waits rather than sending a second snapshot.
                    Err(e) if e.to_string() == tasks::AWAITING_FINALITY => false,
                    Err(_) => false,
                }
            }
            TaskKind::StartVerification => {
                match tasks::start_verification::execute(&self.route, epoch, &self.claim_store, &self.task_store, wallet_address).await {
                    Ok(_) => true,
                    Err(e) if e.to_string() == "PendingReplacement" => false,
                    Err(e) if e.to_string() == tasks::AWAITING_FINALITY => false,
                    Err(e) if e.to_string().contains("Invalid claim") => {
                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
                        true
                    }
                    Err(_) => false,
                }
            }
            TaskKind::VerifySnapshot => {
                match tasks::verify_snapshot::execute(&self.route, epoch, &self.claim_store, &self.task_store, wallet_address).await {
                    Ok(_) => true,
                    Err(e) if e.to_string() == "PendingReplacement" => false,
                    Err(e) if e.to_string() == tasks::AWAITING_FINALITY => false,
                    Err(e) if e.to_string().contains("Invalid claim") => {
                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
                        true
                    }
                    Err(_) => false,
                }
            }
            TaskKind::ExecuteRelay { position, l2_sender, dest_addr, l2_block, l1_block, l2_timestamp, amount, data } => {
                match tasks::execute_relay::execute(
                    &self.config,
                    &self.route,
                    *position,
                    *l2_sender,
                    *dest_addr,
                    *l2_block,
                    *l1_block,
                    *l2_timestamp,
                    *amount,
                    data.clone(),
                    &self.task_store,
                    epoch,
                ).await {
                    Ok(_) => true,
                    // Must precede the catch-all below, or an in-flight relay gets
                    // pushed 30 minutes into the future instead of being replaced.
                    Err(e) if e.to_string() == "PendingReplacement" => false,
                    // Likewise for a relay that is mined but not final: rescheduling it
                    // +30min would be harmless, but keeping it re-checks next cycle.
                    Err(e) if e.to_string() == tasks::AWAITING_FINALITY => false,
                    Err(e) if e.to_string() == "RootNotConfirmed" => {
                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 60 * 60);
                        true
                    }
                    Err(_) => {
                        self.task_store.lock().unwrap().reschedule_task(task, current_timestamp + 30 * 60);
                        true
                    }
                }
            }
            TaskKind::WithdrawDeposit => {
                tasks::withdraw_deposit::execute(&self.route, epoch, &self.claim_store).await.is_ok()
            }
        }
    }
}

use alloy::primitives::U256;
use alloy::providers::Provider;
use std::sync::{Arc, Mutex};
use tracing::{info, warn, error};
use crate::config::{Route, ValidatorConfig};
use crate::contracts::{IVeaInbox, IVeaOutboxArbToEth, IVeaOutboxArbToGnosis, IWETH};
use crate::finality::is_epoch_finalized;
use crate::tasks::{is_in_flight, send_or_replace, was_event_emitted, ClaimStore, Durability, TaskStore};

pub async fn execute(
    config: &ValidatorConfig,
    route: &Route,
    epoch: u64,
    claim_store: &Arc<Mutex<ClaimStore>>,
    task_store: &Arc<Mutex<TaskStore>>,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let inbox = IVeaInbox::new(route.inbox_address, route.inbox_provider.clone());
    let epoch_period: u64 = inbox.epochPeriod().call().await?.try_into()?;

    let finalized = is_epoch_finalized(
        epoch,
        epoch_period,
        &route.inbox_provider,
        &config.ethereum_provider,
        config.sequencer_inbox,
    ).await?;
    if !finalized {
        warn!(logger = "Challenge", route = route.name, epoch, "Epoch not yet finalized on L1");
        return Err("EpochNotFinalized".into());
    }

    let claim = claim_store.lock().unwrap().get_claim(epoch);
    let wallet_address = config.wallet.default_signer().address();

    let result = if let Some(weth_address) = route.weth_address {
        let outbox = IVeaOutboxArbToGnosis::new(route.outbox_address, route.outbox_provider.clone());
        let deposit = outbox.deposit().call().await?;

        let weth = IWETH::new(weth_address, route.outbox_provider.clone());
        let balance = weth.balanceOf(wallet_address).call().await?;
        if balance < deposit {
            error!(logger = "Challenge", route = route.name, epoch, have = %balance, need = %deposit, "Insufficient WETH, will retry");
            return Err("Insufficient funds".into());
        }

        send_or_replace(
            outbox.challenge(U256::from(epoch), claim),
            &route.outbox_provider,
            wallet_address,
            task_store,
            epoch,
            "challenge",
            route.name,
            // Settlement chain (Gnosis): its own `finalized` tag is the bar.
            &Durability::ChainFinalized,
        ).await
    } else {
        let outbox = IVeaOutboxArbToEth::new(route.outbox_address, route.outbox_provider.clone());
        let deposit = outbox.deposit().call().await?;

        let balance = route.outbox_provider.get_balance(wallet_address).await?;
        if balance < deposit {
            error!(logger = "Challenge", route = route.name, epoch, have = %balance, need = %deposit, "Insufficient ETH, will retry");
            return Err("Insufficient funds".into());
        }

        send_or_replace(
            outbox.challenge(U256::from(epoch), claim).value(deposit),
            &route.outbox_provider,
            wallet_address,
            task_store,
            epoch,
            "challenge",
            route.name,
            // Settlement chain (Ethereum): its own `finalized` tag is the bar.
            &Durability::ChainFinalized,
        ).await
    };

    if let Err(e) = result {
        // Still ours - in the mempool, or mined but not final. Falling through would read
        // our own `Challenged` event as another validator's and retire the task, leaving
        // nothing to re-send the challenge if it is reorged out.
        if is_in_flight(e.as_ref()) {
            return Err(e);
        }
        if was_event_emitted(&route.outbox_provider, route.outbox_address, "Challenged(uint256,address)", epoch).await {
            info!(logger = "Challenge", route = route.name, epoch, "Already challenged by another validator");
            return Ok(());
        }
        if was_event_emitted(&route.outbox_provider, route.outbox_address, "VerificationStarted(uint256)", epoch).await {
            info!(logger = "Challenge", route = route.name, epoch, "Verification started, claimHash changed - will retry");
            return Err("VerificationStarted".into());
        }
        return Err(e);
    }
    Ok(())
}

use alloy::primitives::{FixedBytes, U256};
use std::sync::{Arc, Mutex};
use tracing::{info, warn};
use crate::config::{Route, ValidatorConfig};
use crate::contracts::{IVeaInbox, IVeaOutbox, IVeaOutboxArbToEth, IVeaOutboxArbToGnosis};
use crate::finality::is_epoch_finalized;
use crate::tasks::{is_in_flight, send_or_replace, ClaimStore, Durability, TaskStore};

const SEVEN_DAYS_SECS: u32 = 7 * 24 * 3600;

pub async fn execute(
    config: &ValidatorConfig,
    route: &Route,
    epoch: u64,
    claim_store: &Arc<Mutex<ClaimStore>>,
    current_timestamp: u64,
    task_store: &Arc<Mutex<TaskStore>>,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let inbox = IVeaInbox::new(route.inbox_address, route.inbox_provider.clone());
    let epoch_period: u64 = inbox.epochPeriod().call().await?.try_into()?;

    let finalized = is_epoch_finalized(
        epoch,
        epoch_period,
        &route.inbox_provider,
        &config.ethereum_provider,
        config.sequencer_inbox,
    ).await?;
    if !finalized {
        warn!(logger = "Claim", route = route.name, epoch, "Epoch not yet finalized on L1");
        return Err("EpochNotFinalized".into());
    }

    let outbox = IVeaOutbox::new(route.outbox_address, route.outbox_provider.clone());

    let state_root = inbox.snapshots(U256::from(epoch)).call().await?;
    if state_root == FixedBytes::<32>::ZERO {
        info!(logger = "Claim", route = route.name, epoch, "No snapshot");
        return Ok(());
    }

    let claim_hash = outbox.claimHashes(U256::from(epoch)).call().await?;
    if claim_hash != FixedBytes::<32>::ZERO {
        info!(logger = "Claim", route = route.name, epoch, "Already claimed");
        return Ok(());
    }

    let current_state_root = outbox.stateRoot().call().await?;
    if current_state_root == state_root {
        info!(logger = "Claim", route = route.name, epoch, "State root already verified on outbox");
        return Ok(());
    }

    let since = (current_timestamp as u32).saturating_sub(SEVEN_DAYS_SECS);
    if claim_store.lock().unwrap().has_state_root_in_recent_claims(state_root, since) {
        info!(logger = "Claim", route = route.name, epoch, "State root already in pending claim");
        return Ok(());
    }

    let wallet_address = config.wallet.default_signer().address();
    // The one write that is not gated on durability, for two reasons.
    //
    // A gate here would protect nothing. Every early return above - "Already claimed" in
    // particular - happens *before* `send_or_replace` is reached, so once our claim is on
    // chain this function stops at that check and never re-enters the gate to settle the
    // pending record it wrote. The record would then sit in the store forever, one per
    // epoch, pinning a nonce that has long since been consumed.
    //
    // And a reorged-out claim costs nothing: the deposit rides on the claim transaction
    // itself, so if the transaction is undone the deposit is undone with it and no funds
    // are at stake. (`EpochWatcher` records `last_after_epoch` on the first `Ok`, so such a
    // claim is *not* automatically re-sent - the epoch simply goes unclaimed by us, which
    // is the same position as never having claimed it.) Contrast `challenge`, where losing
    // the write silently while the deposit stands is exactly what the gate exists to stop.
    let durability = Durability::Confirmed;
    let result = if route.weth_address.is_some() {
        let gnosis_outbox = IVeaOutboxArbToGnosis::new(route.outbox_address, route.outbox_provider.clone());
        send_or_replace(
            gnosis_outbox.claim(U256::from(epoch), state_root),
            &route.outbox_provider,
            wallet_address,
            task_store,
            epoch,
            "claim",
            route.name,
            &durability,
        ).await
    } else {
        let eth_outbox = IVeaOutboxArbToEth::new(route.outbox_address, route.outbox_provider.clone());
        let deposit = eth_outbox.deposit().call().await?;
        send_or_replace(
            eth_outbox.claim(U256::from(epoch), state_root).value(deposit),
            &route.outbox_provider,
            wallet_address,
            task_store,
            epoch,
            "claim",
            route.name,
            &durability,
        ).await
    };

    if let Err(e) = result {
        // Still in flight - not a failed claim, so don't consult the chain or the
        // caller will read "not claimed yet" and treat it as something to retry fresh.
        if is_in_flight(e.as_ref()) {
            return Err(e);
        }
        let claim_hash = outbox.claimHashes(U256::from(epoch)).call().await?;
        if claim_hash != FixedBytes::<32>::ZERO {
            info!(logger = "Claim", route = route.name, epoch, "Already claimed by another validator");
            return Ok(());
        }
        return Err(e);
    }
    Ok(())
}

use tracing::info;
use crate::config::Route;
use crate::contracts::IVeaInbox;
use crate::tasks::{send_tx, TaskStore};
use std::sync::{Arc, Mutex};

pub async fn execute(
    route: &Route,
    task_store: &Arc<Mutex<TaskStore>>,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let inbox = IVeaInbox::new(route.inbox_address, route.inbox_provider.clone());
    let current_count = inbox.count().call().await?;

    if current_count == 0 {
        info!(logger = "SaveSnapshot", route = route.name, "No messages, skipping");
        return Ok(());
    }

    let last_saved_count = task_store.lock().unwrap().get_last_saved_count().unwrap_or(0);

    if current_count <= last_saved_count {
        info!(logger = "SaveSnapshot", route = route.name, count = current_count, "Nothing new to save");
        return Ok(());
    }

    info!(logger = "SaveSnapshot", route = route.name, from = last_saved_count, to = current_count, "Saving snapshot");
    send_tx(inbox.saveSnapshot().send().await, "saveSnapshot", route.name).await
}
use alloy::primitives::{FixedBytes, U256};
use std::sync::{Arc, Mutex};
use tracing::info;
use crate::config::Route;
use crate::contracts::{IVeaOutbox, Party};
use crate::tasks::{send_tx, ClaimStore};

pub async fn execute(
    route: &Route,
    epoch: u64,
    claim_store: &Arc<Mutex<ClaimStore>>,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let outbox = IVeaOutbox::new(route.outbox_address, route.outbox_provider.clone());

    let claim_hash = outbox.claimHashes(U256::from(epoch)).call().await?;
    if claim_hash == FixedBytes::<32>::ZERO {
        info!(logger = "WithdrawDeposit", route = route.name, epoch, "Already withdrawn");
        claim_store.lock().unwrap().remove(epoch);
        return Ok(());
    }

    let claim = claim_store.lock().unwrap().get_claim(epoch);
    info!(logger = "WithdrawDeposit", route = route.name, epoch, honest = ?claim.honest, "Withdrawing deposit");

    let result = match claim.honest {
        Party::Claimer => {
            send_tx(
                outbox.withdrawClaimDeposit(U256::from(epoch), claim).send().await,
                "withdrawClaimDeposit",
                route.name,
            ).await
        }
        Party::Challenger => {
            send_tx(
                outbox.withdrawChallengeDeposit(U256::from(epoch), claim).send().await,
                "withdrawChallengeDeposit",
                route.name,
            ).await
        }
        _ => panic!("Cannot withdraw - honest party not determined for epoch {}", epoch),
    };

    if let Err(e) = result {
        let claim_hash = outbox.claimHashes(U256::from(epoch)).call().await?;
        if claim_hash == FixedBytes::<32>::ZERO {
            info!(logger = "WithdrawDeposit", route = route.name, epoch, "Already withdrawn by another validator");
            claim_store.lock().unwrap().remove(epoch);
            return Ok(());
        }
        return Err(e);
    }

    claim_store.lock().unwrap().remove(epoch);
    Ok(())
}

use alloy::primitives::{FixedBytes, U256};
use std::sync::{Arc, Mutex};
use tracing::{info, warn, error};
use crate::config::{Route, ValidatorConfig};
use crate::contracts::IVeaInbox;
use crate::finality::is_epoch_finalized;
use crate::tasks::{Task, TaskKind, TaskStore, ClaimStore};

/// The inbox snapshot for `epoch`, read only once that epoch's L2 data is provably
/// finalized on L1.
///
/// This is the only read a verdict may be based on: `snapshots(epoch)` is overwritable
/// until the L2 clock passes epoch end, and an L2 block whose batch is not yet finalized
/// on L1 can still be reordered or backdated by the sequencer. Every caller that decides
/// whether to challenge goes through here.
///
/// Returns the `EpochNotFinalized` sentinel when the epoch is not finalized yet; the
/// dispatcher matches that string exactly, so it must not be wrapped or annotated.
pub async fn finalized_state_root(
    config: &ValidatorConfig,
    route: &Route,
    epoch: u64,
) -> Result<FixedBytes<32>, Box<dyn std::error::Error + Send + Sync>> {
    let inbox = IVeaInbox::new(route.inbox_address, route.inbox_provider.clone());
    let epoch_period: u64 = inbox.epochPeriod().call().await?.try_into()?;

    let finalized = is_epoch_finalized(
        epoch,
        epoch_period,
        &route.inbox_provider,
        &config.ethereum_provider,
        config.sequencer_inbox,
    ).await?;

    if !finalized {
        return Err("EpochNotFinalized".into());
    }

    Ok(inbox.snapshots(U256::from(epoch)).call().await?)
}

pub async fn execute(
    config: &ValidatorConfig,
    route: &Route,
    epoch: u64,
    claim_store: &Arc<Mutex<ClaimStore>>,
    current_timestamp: u64,
    task_store: &Arc<Mutex<TaskStore>>,
) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let correct_state_root = match finalized_state_root(config, route, epoch).await {
        Ok(root) => root,
        Err(e) if e.to_string() == "EpochNotFinalized" => {
            warn!(logger = "ValidateClaim", route = route.name, epoch, "Epoch not yet finalized on L1");
            return Err(e);
        }
        Err(e) => {
            error!(logger = "ValidateClaim", route = route.name, epoch, "Finality check failed: {e}");
            return Err(e);
        }
    };

    let claim_data = claim_store.lock().unwrap().get(epoch);
    let claimed_state_root = claim_data.state_root;

    if claimed_state_root == correct_state_root {
        info!(logger = "ValidateClaim", route = route.name, epoch, "VALID");
        task_store.lock().unwrap().add_task(Task {
            epoch,
            execute_after: current_timestamp + route.settings.start_verification_delay,
            kind: TaskKind::StartVerification,
        });
    } else {
        error!(logger = "ValidateClaim", route = route.name, epoch, claimed = ?claimed_state_root, correct = ?correct_state_root, "INVALID - scheduling challenge");
        task_store.lock().unwrap().add_task(Task {
            epoch,
            execute_after: current_timestamp,
            kind: TaskKind::Challenge,
        });
    }

    Ok(())
}

